#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

struct Recuento {
    int aceptados;
    int rechazados;
};

bool recuento_valido(const Recuento& valor) {
    return valor.aceptados >= 0 && valor.aceptados <= 10
        && valor.rechazados >= 0 && valor.rechazados <= 10;
}

std::istream& operator>>(std::istream& origen, Recuento& destino) {
    char apertura{0};
    char separador{0};
    char cierre{0};
    Recuento candidato{0, 0};
    if (!(origen >> apertura >> candidato.aceptados >> separador
          >> candidato.rechazados >> cierre)) {
        return origen;
    }
    if (apertura != '[' || separador != ';' || cierre != ']'
        || !recuento_valido(candidato)) {
        origen.setstate(std::ios::failbit);
        return origen;
    }
    destino = candidato;
    return origen;
}

struct Registro {
    int id;
    Recuento recuento;
};

bool leer_linea(const std::string& linea, Registro& destino) {
    std::istringstream origen{linea};
    Registro candidato{0, {0, 0}};
    if (!(origen >> candidato.id >> candidato.recuento)
        || candidato.id < 0 || candidato.id > 9) {
        return false;
    }
    origen >> std::ws;
    if (!origen.eof() || origen.bad()) {
        return false;
    }
    destino = candidato;
    return true;
}

bool contiene_id(const std::vector<Registro>& registros, int id) {
    for (const Registro& registro : registros) {
        if (registro.id == id) {
            return true;
        }
    }
    return false;
}

bool cargar_directamente(std::istream& origen, std::vector<Registro>& destino) {
    destino.clear();
    std::string linea;
    while (std::getline(origen, linea)) {
        Registro registro{0, {0, 0}};
        if (!leer_linea(linea, registro)
            || contiene_id(destino, registro.id)) {
            return false;
        }
        destino.push_back(registro);
    }
    return !origen.bad() && origen.eof();
}

int main() {
    std::istringstream origen{"1 [2;0]\n1 [3;1]\n2 [0;0]"};
    std::vector<Registro> destino{{9, {1, 1}}};
    bool completo = cargar_directamente(origen, destino);
    std::cout << (completo ? "Accepted" : "Rejected");
    for (const Registro& registro : destino) {
        std::cout << '|' << registro.id << ':'
                  << registro.recuento.aceptados << ':'
                  << registro.recuento.rechazados;
    }
    return 0;
}

